namespace Tendaa.Core.Models.Entities;

/// <summary>A customer, identified by WhatsApp's business-scoped user id (BSUID) — never by
/// phone number, which is optional since customers can hide it behind a username. See
/// ARCHITECTURE.md's "Customer identity" section.</summary>
public sealed class Customer : IShopScoped
{
    public Guid Id { get; set; }
    public Guid ShopId { get; set; }

    /// <summary>WhatsApp business-scoped user id (`user_id` / `from_user_id`). Always present,
    /// unique per shop. Regenerated by WhatsApp if the customer changes phone number — when that
    /// happens a new value replaces this one on the existing row (see
    /// ARCHITECTURE.md "Customer identity" / BSUID changes), it never creates a new Customer.</summary>
    public required string BsuId { get; set; }

    /// <summary>`wa_id` / `from`. Nullable — omitted once a customer adopts a username and none
    /// of WhatsApp's 30-day/contact-book exceptions apply. Only ever overwritten when a new value
    /// arrives; never cleared just because an event omits it.</summary>
    public string? PhoneNumber { get; set; }

    /// <summary>`contacts[].profile.username`, when WhatsApp sends it.</summary>
    public string? Username { get; set; }

    /// <summary>`contacts[].profile.name`, when WhatsApp sends it.</summary>
    public string? Name { get; set; }

    public DateTimeOffset CreatedAt { get; set; }
}
